let variant='ribbon',view='play';const el=s=>document.querySelector(s);
function render(){const tabs=['play','tune','style','library'];const nav=tabs.map(t=>`<button data-view="${t}" aria-pressed="${view===t}">${t.toUpperCase()}</button>`).join('');let top=variant==='ribbon'?`<div class="sheet"><div class="actions">${nav}</div><div class="control"><label>環境<select id="study-profile"><option>Competitive</option><option>BedWars</option><option>SkyWars</option></select></label></div></div>`:variant==='dock'?`<div class="actions sheet" style="max-width:500px;margin:auto;border-radius:30px">${nav}</div>`:`<div class="actions sheet">${tabs.map((t,i)=>`<button data-view="${t}">${i+1} / ${t.toUpperCase()}</button>`).join('')}</div>`;let body=view==='play'?`<div class="hero"><div><h1>準備は短く。</h1><p>あなたのMinecraft環境。</p>${variant!=='ribbon'?'<label>環境<select id="study-profile"><option>Competitive</option><option>BedWars</option><option>SkyWars</option></select></label>':''}<p><button class="primary" id="study-launch">Play（試作）</button></p></div><div class="sheet"><h2>Environment</h2><p>Java Edition 1.8.9 / Forge</p><p>Competitive preset</p></div></div>`:view==='style'?`<div class="sheet"><h2>STYLE</h2><button id="study-crosshair">Crosshairを編集</button><div id="study-editor"></div></div>`:view==='tune'?`<div class="sheet"><h2>TUNE</h2><label>Preset <select id="study-preset"><option>Competitive</option><option>Maximum FPS</option><option>Balanced</option></select></label><button id="study-crosshair">Crosshairを編集</button><div id="study-editor"></div></div>`:`<div class="sheet"><h2>LIBRARY</h2><label>コンテンツ検索<input id="study-search" placeholder="Resource Pack"></label><button id="study-add">追加候補を見る</button><p id="study-result"></p></div>`;el('#study').innerHTML=top+body;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});if(el('#study-profile'))el('#study-profile').onchange=e=>el('#feedback').textContent='選択: '+e.target.value;if(el('#study-launch'))el('#study-launch').onclick=()=>el('#feedback').textContent='試作の起動操作を確認しました。ゲームは起動しません。';if(el('#study-crosshair'))el('#study-crosshair').onclick=()=>{el('#study-editor').innerHTML='<p>照準 Concept Preview</p><label>色 <input type="color" id="study-color" value="#e6ab32"></label><span id="study-reticle" style="font-size:50px;color:#e6ab32;margin:30px">＋</span>';el('#study-color').oninput=e=>el('#study-reticle').style.color=e.target.value;};if(el('#study-add'))el('#study-add').onclick=()=>el('#study-result').textContent='検索語: '+el('#study-search').value+' / 正規配布APIで取得する設計。ここはUI試作です。';if(el('#study-preset'))el('#study-preset').onchange=e=>el('#feedback').textContent='Preset選択: '+e.target.value;}
document.querySelectorAll('[data-variant]').forEach(b=>b.onclick=()=>{variant=b.dataset.variant;view='play';document.querySelectorAll('[data-variant]').forEach(x=>x.setAttribute('aria-pressed',x===b));render();});render();
